#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string firstLine;
    getline(cin, firstLine);
    stringstream ss(firstLine);
    int n, m;
    ss >> n >> m;

    long long dp[n][n * n + 5];
    memset(dp, 0, sizeof(dp));
    dp[0][0] = 1;

    for (int i = 1; i < n; i++) {
        for (int j = 0; j < (int)sizeof(dp[0]) / sizeof(long long); j++) {
            for (int c = 0; c <= i; c++) {
                if (j - c >= 0) {
                    dp[i][j] += dp[i - 1][j - c];
                    dp[i][j] %= m;
                    if (dp[i][j] == 0) dp[i][j] += m;
                }
            }
        }
    }

    long long sums[n][n * n + 5];
    for (int i = 0; i < n; i++) {
        long long s = 0;
        for (int j = 0; j < (int)sizeof(dp[0]) / sizeof(long long); j++) {
            s += dp[i][j];
            s %= m;
            if (s == 0) s += m;
            sums[i][j] = s;
        }
    }

    long long fact[501 * 501];
    fact[0] = 1;
    for (int i = 1; i < 501 * 501; i++) {
        fact[i] = (fact[i - 1] * i) % m;
    }

    long long ncr[501][501];
    memset(ncr, 0, sizeof(ncr));
    ncr[0][0] = 1;
    for (int i = 1; i <= 500; i++) {
        ncr[i][0] = 1;
        for (int j = 1; j <= 500; j++) {
            ncr[i][j] = (ncr[i - 1][j] + ncr[i - 1][j - 1]) % m;
            if (ncr[i][j] == 0) ncr[i][j] += m;
        }
    }

    long long result = 0;
    for (int i = n - 2; i >= 0; i--) {
        int cnt = n - i;
        int pre = n - cnt;
        long long comb = (ncr[n][pre] * fact[pre]) % m;
        if (comb == 0) comb += m;
        long long sum = 0;
        for (int dif = 1; dif < cnt; dif++) {
            for (int inv = dif; inv < (int)sizeof(dp[0]) / sizeof(long long); inv++) {
                if (dp[cnt - 2][inv] == 0) break;
                if (inv - dif - 1 < 0) continue;
                long long x = dp[cnt - 2][inv];
                long long y = sums[cnt - 2][inv - dif - 1];
                x = (x * y) % m;
                if (x == 0) x += m;
                sum += (x * (cnt - dif)) % m;
                sum %= m;
            }
        }
        result += sum * comb;
        result %= m;
        if (result == 0) result += m;
    }
    cout << result % m << "\n";

    return 0;
}
